func detectMirrorClone(ctx context.Context, repoRoot string) *mirrorClone {
	for _, name := range orderedRemoteNames(ctx, repoRoot) {
		rawURL, gerr := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
		if gerr != nil {
			continue
		}
		info, perr := gitremote.ParseURL(rawURL)
		if perr != nil || info.Protocol != gitremote.ProtocolEntire {
			continue
		}
		return &mirrorClone{
			Remote:  name,
			Cluster: info.Host,
			Owner:   info.Owner,
			Repo:    info.Repo,
			URL:     rawURL,
		}
	}
	return nil
}

// forgeMirrorHint names the GitHub repo this clone could be mirrored from, for
// the "not mirrored" hint. ok is false when no remote names a mirrorable GitHub
// repo — mirrors are GitHub-only, so there would be nothing to suggest.
func forgeMirrorHint(ctx context.Context, repoRoot string) (owner, repo string, ok bool) {
	for _, name := range orderedRemoteNames(ctx, repoRoot) {
		rawURL, gerr := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
		if gerr != nil {
			continue
		}
		info, perr := gitremote.ParseURL(rawURL)
		if perr != nil {
			continue
		}
		// An entire:// remote is already a mirror; only a direct forge remote is
		// a candidate to mirror.
		if info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorForge {
			return info.Owner, info.Repo, true
		}
	}
	return "", "", false
}

// orderedRemoteNames lists the repo's git remotes with origin first, then the
// rest by name, so both the mirror scan and the hint report a stable,
// origin-preferring result. Returns nil on any error (treated as "no remotes").
func orderedRemoteNames(ctx context.Context, repoRoot string) []string {
	remotes, err := gitremote.ListRemotesInDir(ctx, repoRoot)
	if err != nil || len(remotes) == 0 {
		return nil
	}
	var hasOrigin bool
	rest := make([]string, 0, len(remotes))
	for _, name := range remotes {
		if name == originRemote {
			hasOrigin = true
			continue
		}
		rest = append(rest, name)
	}
	sort.Strings(rest)
	if hasOrigin {
		return append([]string{originRemote}, rest...)
	}
	return rest
}

