// formatMirrorHint renders the one-line "this repo isn't mirrored, here's how"
// hint shown when the clone targets the forge directly.
func formatMirrorHint(owner, repo string, sty statusStyles) string {
	return fmt.Sprintf("%s This repo is not mirrored. Set up an Entire mirror with:\n    %s",
		sty.render(sty.dim, "⇄"),
		sty.render(sty.bold, fmt.Sprintf("entire repo mirror create github.com/%s/%s", owner, repo)),
	)
}

// writeMirrorStatus renders the mirror line when this clone points at a mirror,
// or a hint on how to set one up when it targets a GitHub forge directly. Both
// paths are decided from local git config; the live-status lookup only fires for
// mirror-using repos, and the hint triggers no network at all.
func writeMirrorStatus(ctx context.Context, w io.Writer, repoRoot string, sty statusStyles) {
	if m := detectMirrorClone(ctx, repoRoot); m != nil {
		status, loggedIn := resolveMirrorStatus(ctx, m)
		fmt.Fprintln(w, formatMirrorStatusLine(m, status, loggedIn, sty))
		return
	}
	if owner, repo, ok := forgeMirrorHint(ctx, repoRoot); ok {
		fmt.Fprintln(w, formatMirrorHint(owner, repo, sty))
	}
}

